import java.util.*; import java.io.*; public class TestClass { static class Edge { int to; long cost; Edge(int to, long cost) { this.to = to; this.cost = cost; } } static class State implements Comparable<State> { int u; long stamina; long sleep; State(int u, long stamina, long sleep) { this.u = u; this.stamina = stamina; this.sleep = sleep; } public int compareTo(State o) { return Long.compare(this.sleep, o.sleep); } } public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int N = Integer.parseInt(st.nextToken()); int M = Integer.parseInt(st.nextToken()); int A = Integer.parseInt(st.nextToken()); int B = Integer.parseInt(st.nextToken()); List<List<Edge>> adj = new ArrayList<>(); for (int i = 0; i <= N; i++) adj.add(new ArrayList<>()); for (int i = 0; i < M; i++) { st = new StringTokenizer(br.readLine()); int u = Integer.parseInt(st.nextToken()); int v = Integer.parseInt(st.nextToken()); long z = Long.parseLong(st.nextToken()); adj.get(u).add(new Edge(v, z)); adj.get(v).add(new Edge(u, z)); } long[] C = new long[N + 1]; long[] H = new long[N + 1]; for (int i = 1; i <= N; i++) { st = new StringTokenizer(br.readLine()); C[i] = Long.parseLong(st.nextToken()); H[i] = Long.parseLong(st.nextToken()); } PriorityQueue<State> pq = new PriorityQueue<>(); Map<String, Long> dist = new HashMap<>(); pq.add(new State(A, 0, 0)); dist.put(A + "," + 0, 0L); while (!pq.isEmpty()) { State curr = pq.poll(); if (curr.sleep > dist.getOrDefault(curr.u + "," + curr.stamina, Long.MAX_VALUE)) continue; if (curr.u == B) { System.out.println(curr.sleep); return; } for (Edge e : adj.get(curr.u)) { if (curr.stamina >= e.cost) { long nextSleep = curr.sleep; long nextStamina = curr.stamina - e.cost; String key = e.to + "," + nextStamina; if (nextSleep < dist.getOrDefault(key, Long.MAX_VALUE)) { dist.put(key, nextSleep); pq.add(new State(e.to, nextStamina, nextSleep)); } } } long nextSleep = curr.sleep + H[curr.u]; long nextStamina = C[curr.u]; String key = curr.u + "," + nextStamina; if (nextSleep < dist.getOrDefault(key, Long.MAX_VALUE)) { dist.put(key, nextSleep); pq.add(new State(curr.u, nextStamina, nextSleep)); } } System.out.println(-1); } }